import numpy as np


def _case(seed, B, i, o):
    r = np.random.default_rng(seed)
    return r.normal(size=(B, i)), r.normal(size=(i, o)), r.normal(size=o), r.normal(size=(B, o))


def _cd_ok():
    x, W, b, d = _case(11, 3, 4, 5)
    if np.abs(x @ W + b).min() < 1e-3:
        return False
    f = lambda x, W, b: float((d * np.maximum(x @ W + b, 0)).sum())
    got = linear_relu_backward(x, W, b, d)
    worst = 0.0
    for k, A in enumerate((x, W, b)):
        for i in np.ndindex(A.shape):
            P = [x.copy(), W.copy(), b.copy()]; M = [x.copy(), W.copy(), b.copy()]
            P[k][i] += 1e-6; M[k][i] -= 1e-6
            num = (f(*P) - f(*M)) / 2e-6
            worst = max(worst, abs(num - got[k][i]))
    return worst < 1e-6
